"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3910],{36894:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainGuideController","desc":"First-spawn hint that shows new players where the brake lever is. On the\\nplayer\'s first character spawn, if the train has not started yet\\n(Workspace attribute `TrainConfig.STARTED_ATTR` is not true), it builds a\\nflat Neon chevron at chest height in front of the\\nplayer that turns every frame to face the\\nnearest `TrainConfig.BRAKE_LEVER_TAG` lever, plus a pulsing Neon ring on the\\nfloor under that lever. Both go away on the first un-brake (any player) or\\nwhen the character dies, and never come back this server session:\\nStarterPlayerScripts survive respawn, so the script-level `shown` flag holds.\\nTuning: `TrainConfig.GUIDE_*`.","realm":["Client"],"source":{"line":17,"path":"src/StarterPlayer/StarterPlayerScripts/TrainGuideController.client.luau"}}')}}]);